    description: 'Токсичное трудолюбие (трудоголизм) - это когда кто-либо упахивается как лошадь и/или упахивает коллег/подчинённых сверх обозначенных трудовым договором норм. Или делает вид, что упахивается. Токсичный трудоголизм (ТТ) бывает двух направлений и оба они неправильные: по отношению к другим и по отношению к себе. Разберём эти случаи и их последствия.',
